119	                    return { success: false, error: rpcError.message };
120	                }
121	                if (rpcError.message?.includes('Carteira nao encontrada')) {
122	                    return { success: false, error: 'Carteira nao encontrada' };
123	                }
124	                if (rpcError.code === '23505') {
125	                    return { success: false, error: 'Escrow ja existe para esta vaga' };
126	                }
127	                throw rpcError;
128	            }
129	
130	            return { success: true };
131	        } catch (error) {
132	            logError('Error reserving escrow', error);
133	            return { success: false, error: 'Erro ao reservar pagamento' };
134	        }
135	    },
136	
137	    async createDeposit(payload: { amount: number, name?: string, cpfCnpj?: string, billingType?: string }): Promise<{ paymentId?: string; invoiceUrl?: string; pixQrCodeUrl?: string; error?: string }> {
138	        try {
139	            return await invokeFunction('asaas-deposit', payload);
140	        } catch (error: unknown) {
141	            logError('Error creating deposit', error);
142	            return { error: error instanceof Error ? error.message : 'Erro ao criar deposito via Asaas' };
143	        }
144	    },
145	
146	    async syncBalance(): Promise<{ success: boolean; hasUpdates?: boolean; totalSynced?: number; message?: string; error?: string }> {
147	        try {
148	            return await invokeFunction('asaas-sync', {});
149	        } catch (error: unknown) {
150	            logError('Error syncing balance', error);
151	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao sincronizar saldo' };
152	        }
153	    },
154	
155	    async releaseEscrow(jobId: string, applicationId: string, workerUserId: string): Promise<{ success: boolean; error?: string }> {
156	        try {
157	            await invokeFunction('asaas-checkout', { jobId, applicationId, workerId: workerUserId });
158	            return { success: true };
159	        } catch (error: unknown) {
160	            logError('Error releasing escrow', error);
161	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao liberar pagamento' };
162	        }
163	    },
164	
165	    async refundEscrow(jobId: string, reason?: string): Promise<{ success: boolean; error?: string }> {
166	        try {
167	            const { error: rpcError } = await supabase.rpc('refund_escrow', {
168	                p_job_id: jobId,
169	                p_reason: reason || 'Reembolso de vaga cancelada'
170	            });
171	
172	            if (rpcError) {
173	                if (rpcError.message?.includes('No reserved escrow')) {
174	                    return { success: true };
175	                }
176	                throw rpcError;
177	            }
178	
179	            return { success: true };
180	        } catch (error) {
181	            logError('Error refunding escrow', error);
182	            return { success: false, error: 'Erro ao reembolsar' };
183	        }
184	    },
185	
186	    async getJobEscrow(jobId: string): Promise<EscrowTransaction | null> {
187	        const { data } = await supabase
188	            .from('escrow_transactions')
189	            .select('*')
190	            .eq('job_id', jobId)
191	            .single();
192	
193	        return data as EscrowTransaction | null;
194	    },
195	
196	    /**
197	     * Libera ou captura o escrow dependendo do kind do turno.
198	     *
199	     * kind='prepaid' (pull legado): invoca asaas-checkout → release_escrow.
200	     * kind='postpaid' (push Slice 2): invoca asaas-capture-payment → capture_escrow_postpago.
201	     *
202	     * Este é o ponto de ramificação por kind para a empresa confirmar a conclusão do turno.
203	     * Deve substituir chamadas diretas a releaseEscrow em fluxos que podem ser postpago.
204	     *
205	     * @param jobId      UUID do turno.
206	     * @param workerId   UUID do worker.
207	     * @param escrowKind 'prepaid' | 'postpaid'. Se omitido, busca do DB.
208	     */
209	    async releaseOrCaptureEscrow(
210	      jobId: string,
211	      workerId: string,
212	      escrowKind?: 'prepaid' | 'postpaid'
213	    ): Promise<{ success: boolean; error?: string }> {
214	      try {
215	        // Se kind não foi passado, buscar do DB
216	        let kind = escrowKind;
217	        if (!kind) {
218	          const { data: escrow } = await supabase
219	            .from('escrow_transactions')
220	            .select('kind')
221	            .eq('job_id', jobId)
222	            .maybeSingle();
223	          kind = (escrow?.kind as 'prepaid' | 'postpaid' | undefined) ?? 'prepaid';
224	        }
225	
226	        let result: { success: boolean; error?: string };
227	        if (kind === 'postpaid') {
228	          result = await PaymentMethodService.capturePayment(jobId, workerId);
229	        } else {
230	          // prepaid: fluxo legado (asaas-checkout → release_escrow)
231	          result = await WalletService.releaseEscrow(jobId, '', workerId);
232	        }
233	
234	        // Avaliar alerta de teto FORA da RPC de saldo (best-effort, NÃO bloqueia o pagamento).
235	        // Buscar companyId via job_id → jobs.company_id (necessário para o alerta).
236	        if (result.success) {
237	          void (async () => {
238	            try {
239	              const { data: jobRow } = await supabase
240	                .from('jobs')
241	                .select('company_id')
242	                .eq('id', jobId)
243	                .maybeSingle();
244	              const companyId = (jobRow as { company_id?: string } | null)?.company_id;
245	              if (companyId) {
246	                await SpendLimitService.evaluateSpendAlert(companyId);
247	              }
248	            } catch (alertErr) {
249	              // Best-effort — nunca propaga para não quebrar o pagamento
250	              logError('walletService.releaseOrCaptureEscrow.spendAlert', alertErr);
251	            }
252	          })();
253	        }
254	
255	        return result;
256	      } catch (error) {
257	        logError('walletService.releaseOrCaptureEscrow', error);
258	        return { success: false, error: 'Erro ao processar pagamento do turno.' };
259	      }
260	    },
261	
262	    async getCompanyEscrows(companyUserId: string): Promise<EscrowTransaction[]> {
263	        const { data: wallet } = await supabase
264	            .from('wallets')
265	            .select('id')
266	            .eq('user_id', companyUserId)
267	            .single();
268	
269	        if (!wallet) return [];
270	
271	        const { data } = await supabase
272	            .from('escrow_transactions')
273	            .select('*, job:jobs(title)')
274	            .eq('company_wallet_id', wallet.id)
275	            .order('created_at', { ascending: false });
276	
277	        return (data || []) as EscrowTransaction[];
278	    }
279	};
